    recent_window = min(20, len(my_history))
    if recent_window > 0:
        recent_actions = my_history[-recent_window:]
        my_coop_rate = recent_actions.count('cooperate') / recent_window
    else:
        my_coop_rate = 0.5  # default if no history

    # Cooperate if recipient reputation is sufficiently high,
    # OR if we have been cooperative in most recent rounds and reputation is at least neutral,
    # OR if we just defected last round (to attempt to rebuild trust).
    last_action_defected = len(my_history) > 0 and my_history[-1] == 'defect'

