    condition_b = (recipient_reputation > 0.0) and (my_coop_rate > 0.6)
    condition_c = last_action_defected and (recipient_reputation > -0.2)

    return condition_a or condition_b or condition_c

def evaluate(current_reputation, observation, my_history, round_num):
    # Use exponential moving average (EWMA) of partner actions to compute trust.
    # Smoothing factor = 0.3; higher trust from recent cooperation.
    if len(my_history) == 0:
        trust = 0.0
    else:
        # Start with a neutral value, then update sequentially.
        trust = 0.0
        for entry in my_history:
            val = 1.0 if entry['partner_action'] == 'cooperate' else -1.0
            trust = 0.3 * val + 0.7 * trust  # EWMA
    # Update reputation based on observed action, modulated by trust.
    if observation['action'] == 'cooperate':
        # Reward cooperation: base 0.4 plus 0.6 * trust
        update = 0.4 + 0.6 * trust
    else:
        # Punish defection: base -0.4 minus 0.6 * trust (more negative when trust is high)
        update = -0.4 - 0.6 * trust
    # Clamp to [-1, 1]
    return max(-1.0, min(1.0, update))


def decide(recipient_reputation, round_num, my_history):
    # Determine threshold using reputation and round number.
    # Base threshold: 0.2 (slightly cooperative bias).
    # Reputation effect: higher reputations lower threshold (more likely to cooperate)
    threshold = 0.2 - 0.5 * recipient_reputation
    # Early round effect: be extra cooperative in the first 20 rounds.
    if round_num < 20:
        threshold -= 0.15 * (1 - round_num / 20.0)

    # Compute a simple average of the last 10 partner actions (or all if fewer).
    if not my_history:
        return True  # default cooperate when no history (generous)
    window = my_history[-10:] if len(my_history) >= 10 else my_history
    total = 0.0
    for entry in window:
        total += 1.0 if entry['partner_action'] == 'cooperate' else -1.0
    avg_score = total / len(window)  # in [-1, 1]

    # Decision: cooperate if average score is at least the threshold.
    return avg_score >= threshold
